    /// <summary>
    /// Creates a link for the given invoice; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.HttpUrl> CreateInvoiceLinkAsync(string businessConnectionId = default, InputMessageContent invoice = default)
    {

           using var activity =  StartCallActivity("CreateInvoiceLinkAsync", typeof(CreateInvoiceLink).FullName ?? "CreateInvoiceLinkAsync");

           try
           {
             return client.CreateInvoiceLinkAsync(businessConnectionId, invoice);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
